  'cdi-rebuild-new-location': { title: 'Rebuilding at a Different Location: Your Rights Under California Law', description: 'California law guarantees that total loss policyholders can rebuild or purchase at a new location without losing benefits. The CDI Commissioner\'s Opinion on CIC 2051.5(c) answers three critical questions about this right.' },
  'cdi-right-to-claim-documents': { title: 'Your Right to Claim Documents: What Insurers Must Provide Under California Law', description: 'California law requires insurers to provide all claim-related documents within 15 days of your request. Most policyholders don\'t know this right exists. Here is the CDI\'s official notice explaining what you\'re entitled to.' },
  'xactimate-overhead-profit': { title: 'Overhead and Profit: When Your Insurance Company Owes It and Why They Refuse', description: 'Insurance carriers routinely deny overhead and profit on repair estimates. The \'three-trade rule\' they cite has no legal basis. Here is what O&P actually is, when it\'s owed, and how to fight the denial.' },
  'xactimate-how-it-works': { title: 'How Xactimate Works: A Policyholder\'s Guide to Insurance Estimates', description: 'Xactimate is the software insurance companies use to price your claim. Understanding how it works — regional pricing databases, line items, labor settings, and its limitations — is the first step to getting paid fairly.' },
