  'fair-plan-claims-limitations': { title: 'The FAIR Plan Claims Process: What 610,000 Policyholders Need to Know', description: 'How to file a FAIR Plan claim, what the FAIR Plan covers and excludes, the $3M residential cap, the current crisis with 610K+ policies, AB 1680 and AB 226 reforms, and why a DIC policy is essential.' },
  'hail-damage-courts-narrowing': { title: 'The Shrinking Definition of Hail Damage: How Courts and Insurers Are Raising the Bar', description: 'Courts and insurers are increasingly defining hail damage more narrowly, requiring functional impairment rather than cosmetic impact. What policyholders need to know.' },
