  'home-renovation-insurance-coverage': { title: 'Home Insurance During Renovation: The Coverage Gaps That Catch Homeowners Mid-Project', description: 'Renovating your home can create serious insurance coverage gaps. Learn how the increase in hazard condition, vacancy triggers, contractor liability exposure, and permit issues affect your homeowner policy during construction.' },
  'how-long-do-claims-take': { title: 'How Long Does a Homeowner Insurance Claim Take? Realistic Timelines by Claim Type', description: 'Realistic timelines for homeowner insurance claims by type — water damage, fire, mold, roof, and wildfire. Covers California regulatory deadlines, common causes of delay, and when delay becomes actionable bad faith.' },
