  'septic-system-coverage': { title: 'Does Homeowner Insurance Cover Septic System Failures? What You Need to Know', description: 'Septic system failures are expensive and rarely covered by standard homeowner policies. Learn what is excluded, what may be covered under specific perils, and how to close dangerous coverage gaps.' },
  'service-line-coverage': { title: 'Service Line Coverage: Protecting the Underground Infrastructure Your Standard Policy Ignores', description: 'What service line coverage is, why standard homeowners policies exclude underground utility lines, what endorsements cover, typical costs, common claims, and how to add this valuable protection to your policy.' },
